/**
 * RayNeo WebXR Extension - Injected bundle (MAIN world content script)
 * Auto-generated from rayneo-hid.js + webxr-polyfill.js + injected.js
 * + youtube-vr.js.
 * Injected as a MAIN-world content script so page CSP (YouTube, etc.)
 * cannot block it. Run: ./build-bundle.sh to regenerate.
 * Do not edit this file by hand.
 */
/**
 * RayNeo HID Driver for WebXR Extension
 * Handles WebHID communication with RayNeo (TCL) AR glasses.
 *
 * Protocol (community reverse-engineering, verified on an Air 4 Pro; derived from
 * verncat/RayNeo-Air-3S-Pro-OpenVR, Fuut4/rayneo-pin and
 * informalTechCode/RayNeo-Air-Series-3DoF-Scaffold):
 * - Host -> glasses: 64-byte output report, frame[0]=0x66, frame[1]=cmd, frame[2]=value
 * - Glasses -> host: input report, frame[0]=0x99, frame[1]=type
 * - IMU frames (type 0x65), little-endian:
 *     accel  float[3] m/s²   @ offset 4
 *     gyro   float[3] deg/s  @ offset 16
 *     temp   float °C        @ offset 28
 *     tick   uint32 (100 µs) @ offset 40
 *     prox   float           @ offset 44
 * - Commands: 0x01/0x02 IMU on/off, 0x06/0x07 SBS 3D / 2D display, 0x20/0x21 panel 60/120 Hz
 *
 * Device frame: x right, y up, z toward the face (forward = -z) — matches the
 * WebXR viewer frame (x right, y up, -z forward), so the fusion quaternion
 * (device -> world) maps 1:1 onto the WebXR view orientation.
 *
 * IMPORTANT difference from the Viture driver: RayNeo glasses stream raw
 * accelerometer + gyro only (no onboard orientation estimate), so this driver
 * runs a Mahony complementary filter with gyro-bias calibration in JavaScript.
 */

// Debug flag - set to true for verbose logging
const RAYNEO_DEBUG = false;

function debugLog(...args) {
  if (RAYNEO_DEBUG) console.log(...args);
}

// USB identifiers: Air 3S Pro and Air 4 Pro share them (they cannot be
// distinguished by VID/PID alone).
const RAYNEO_VIDS = [0x1bbb, 0x0f65];
const RAYNEO_PID = 0xaf50;

const DEG = Math.PI / 180;

// ---------------------------------------------------------------------------
// Minimal quaternion math ({w, x, y, z} objects)
// ---------------------------------------------------------------------------

function quatMul(a, b) {
  return {
    w: a.w * b.w - a.x * b.x - a.y * b.y - a.z * b.z,
    x: a.w * b.x + a.x * b.w + a.y * b.z - a.z * b.y,
    y: a.w * b.y - a.x * b.z + a.y * b.w + a.z * b.x,
    z: a.w * b.z + a.x * b.y - a.y * b.x + a.z * b.w
  };
}

function quatConj(q) {
  return { w: q.w, x: -q.x, y: -q.y, z: -q.z };
}

function quatNorm(q) {
  const m = Math.hypot(q.w, q.x, q.y, q.z);
  if (m < 1e-12) return { w: 1, x: 0, y: 0, z: 0 };
  return { w: q.w / m, x: q.x / m, y: q.y / m, z: q.z / m };
}

function quatAxisAngle(ax, angle) {
  const s = Math.sin(angle / 2);
  const m = Math.hypot(ax[0], ax[1], ax[2]) || 1;
  return { w: Math.cos(angle / 2), x: ax[0] / m * s, y: ax[1] / m * s, z: ax[2] / m * s };
}

// Rotate vector v by quaternion q (v is an [x, y, z] array)
function quatRotate(q, v) {
  const qv = { w: 0, x: v[0], y: v[1], z: v[2] };
  const t = quatMul(quatMul(q, qv), quatConj(q));
  return [t.x, t.y, t.z];
}

// Quaternion that rotates unit vector a onto unit vector b
function quatFromTo(a, b) {
  const d = a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  if (d > 0.999999) return { w: 1, x: 0, y: 0, z: 0 };
  if (d < -0.999999) {
    // 180° about any axis orthogonal to a
    let ax = [1, 0, 0];
    if (Math.abs(a[0]) > 0.9) ax = [0, 1, 0];
    const orth = [
      ax[1] * a[2] - ax[2] * a[1],
      ax[2] * a[0] - ax[0] * a[2],
      ax[0] * a[1] - ax[1] * a[0]
    ];
    return quatAxisAngle(orth, Math.PI);
  }
  const cross = [
    a[1] * b[2] - a[2] * b[1],
    a[2] * b[0] - a[0] * b[2],
    a[0] * b[1] - a[1] * b[0]
  ];
  return quatNorm({ w: 1 + d, x: cross[0], y: cross[1], z: cross[2] });
}

// ---------------------------------------------------------------------------
// Driver
// ---------------------------------------------------------------------------

class RayNeoHID {
  // USB identifiers
  static VENDOR_IDS = RAYNEO_VIDS;
  static PRODUCT_IDS = [RAYNEO_PID];

  static get ALL_DEVICE_IDS() {
    const ids = [];
    for (const vid of RAYNEO_VIDS) ids.push({ vendorId: vid, productId: RAYNEO_PID });
    return ids;
  }

  // Fusion tuning
  static KP = 0.5;                 // Mahony proportional gain
  static CALIB_SAMPLES = 150;      // ~1.3 s of still samples for startup bias calibration
  static CALIB_MAX_GYRO = 3 * DEG; // rad/s per axis allowed during calibration

  constructor() {
    this.device = null;
    this._allDevices = null;
    this.connected = false;
    this.quaternion = { w: 1, x: 0, y: 0, z: 0 }; // pose quaternion (viewer -> world)
    this.callbacks = new Set();

    // Fusion state
    this._initialized = false;
    this._q = { w: 1, x: 0, y: 0, z: 0 }; // device -> world (raw fusion output)
    this._bias = [0, 0, 0];               // gyro bias, rad/s
    this._lastTick = null;
    this._rejectTime = 0;

    // Startup calibration
    this._calCount = 0;
    this._calSum = [0, 0, 0];
    this._calibrated = false;

    // Rest detection (VQF-style) for continuous bias refinement
    this._lpGyro = [0, 0, 0];
    this._lpAcc = [0, 0, 0];
    this._stillTime = 0;

    // Yaw reference for recentering
    this._yawRef = null;

    // IMU stream watchdog
    this._lastReportTime = 0;
    this._watchdog = null;
    this._imuOn = false;
    this._watchWarned = false;
    this._unparsedLogged = 0;
    // Output report IDs to try (0x00 = unnumbered, then common vendor IDs)
    this._outputReportIds = [0x00, 0x66];

    // Desired display mode (true = side-by-side stereo). Kept in the driver
    // so the mode can be re-asserted when the glasses wake from sleep or when
    // a mode command races the display controller's initialization.
    this._stereoOn = false;
    this._stereoTimers = [];

    // Diagnostics counters
    this._reportCount = 0;
    this._imuCount = 0;
    this._lastUnparsedHex = '';

    // Watch for the glasses being plugged in / unplugged so connection state
    // stays truthful everywhere (extension popup, polyfill, sites). The
    // 'connect'/'disconnect' events fire for devices this page holds a
    // persistent WebHID grant for - i.e. once the user has authorized the
    // glasses. Without these, the popup only learns about (dis)connects that
    // happen through this page's own connect()/disconnect() calls.
    if (RayNeoHID.isSupported()) {
      navigator.hid.addEventListener('connect', (event) => {
        if (!this._isRayneoDevice(event.device)) return;
        debugLog('RayNeo: glasses plugged in');
        if (!this.connected) {
          // Re-open with the existing (persistent) grant - no gesture needed
          this.checkExistingConnection().catch(() => {});
        }
      });
      navigator.hid.addEventListener('disconnect', (event) => {
        if (!this._isRayneoDevice(event.device)) return;
        debugLog('RayNeo: glasses unplugged');
        if (this.connected) {
          this._markDisconnected();
        }
      });
    }

    // Last-resort display restore: when this page goes away (tab closed or
    // navigated), its XR session is destroyed without end() running and the
    // glasses would be left in side-by-side mode. Fire the 2D command without
    // awaiting - the browser may or may not flush it before the HID
    // connection is torn down. The extension's tab-close tracking
    // (background.js) is the reliable path.
    window.addEventListener('pagehide', () => {
      if (!this.connected) return;
      if (window.__rayneoAutoModeSwitch !== false) {
        this._sendCommand(0x07).catch(() => {}); // 2D display
      }
      this._sendCommand(0x02).catch(() => {}); // IMU off
    });

    // Answer "are the glasses connected on this page?" queries from the
    // extension: the background service worker loses its in-memory state
    // whenever Chrome stops it (MV3), so the popup reconciles against pages.
    window.addEventListener('message', (event) => {
      if (event.source !== window) return;
      if (event.data && event.data.type === 'RAYNEO_GET_DEVICE_STATE') {
        window.postMessage({
          type: 'RAYNEO_DEVICE_STATE_RESPONSE',
          connected: this.connected,
          deviceInfo: this.connected ? this._getDeviceInfo() : null
        }, '*');
      }
    });
  }

  static isSupported() {
    return 'hid' in navigator;
  }

  _matches(device) {
    return RAYNEO_VIDS.includes(device.vendorId) && device.productId === RAYNEO_PID;
  }

  _isRayneoDevice(device) {
    return !!device && RAYNEO_VIDS.includes(device.vendorId) && device.productId === RAYNEO_PID;
  }

  // Stop tracking the glasses and tell the extension they are gone (physical
  // unplug or dropped device). The popup and sites update via the
  // DEVICE_DISCONNECTED message chain.
  _markDisconnected() {
    if (this._watchdog) {
      clearInterval(this._watchdog);
      this._watchdog = null;
    }
    // Cancel pending stereo re-asserts: the session that requested SBS lost
    // the glasses, so it must not re-enable SBS after a reconnect
    for (const t of this._stereoTimers) clearTimeout(t);
    this._stereoTimers = [];
    this._stereoOn = false;
    this.device = null;
    this._allDevices = null;
    this.connected = false;
    this._imuOn = false;
    // Force fresh IMU init / gyro-bias calibration when the glasses return
    this._initialized = false;
    this._calibrated = false;

    window.postMessage({ type: 'RAYNEO_DEVICE_DISCONNECTED' }, '*');
  }

  // After a fresh connection, make sure the panel is in normal 2D mode: a
  // previous session's page may have gone away without end() running (tab
  // closed / navigated), leaving the glasses in side-by-side mode. Skipped
  // when another tab is currently presenting VR content (the extension
  // reports which tabs have a live immersive session).
  _reset2DIfIdle() {
    const onStatus = (event) => {
      if (event.source !== window) return;
      if (!event.data || event.data.type !== 'RAYNEO_VR_STATUS_RESPONSE') return;
      window.removeEventListener('message', onStatus);
      clearTimeout(timeout);
      if (!event.data.active && window.__rayneoAutoModeSwitch !== false) {
        debugLog('RayNeo: no VR session active anywhere - resetting display to 2D');
        this._sendCommand(0x07).catch(() => {});
      }
    };
    const timeout = setTimeout(() => window.removeEventListener('message', onStatus), 1000);
    window.addEventListener('message', onStatus);
    window.postMessage({ type: 'RAYNEO_GET_VR_STATUS' }, '*');
  }

  async connect() {
    if (!RayNeoHID.isSupported()) {
      throw new Error('WebHID not supported');
    }

    // Request device (user picks one; both known VID variants are offered)
    const selectedDevices = await navigator.hid.requestDevice({
      filters: RayNeoHID.ALL_DEVICE_IDS
    });

    if (selectedDevices.length === 0) {
      throw new Error('No RayNeo device selected');
    }

    console.log('RayNeo: User selected', selectedDevices.length, 'device(s)');

    // After user authorizes, get ALL authorized RayNeo interfaces
    const allAuthorized = await navigator.hid.getDevices();
    const rayneoDevices = allAuthorized.filter(d => this._matches(d));

    console.log(`RayNeo: Found ${rayneoDevices.length} authorized RayNeo device(s)`);

    // Open and listen on ALL of them (only the vendor/IMU interface will
    // produce 0x99 frames; the others are ignored by the parser)
    for (let i = 0; i < rayneoDevices.length; i++) {
      const device = rayneoDevices[i];
      try {
        if (!device.opened) {
          await device.open();
        }
        device.addEventListener('inputreport', (event) => this._handleInputReport(event, i));
        console.log(`RayNeo: Device ${i + 1} ready (${device.productName})`);
      } catch (e) {
        console.warn(`RayNeo: Failed to open device ${i + 1}:`, e.message);
      }
    }

    this.device = rayneoDevices[0];
    this._allDevices = rayneoDevices;
    this.connected = true;

    await this._startIMU();

    // Notify extension
    window.postMessage({
      type: 'RAYNEO_DEVICE_CONNECTED',
      deviceInfo: this._getDeviceInfo()
    }, '*');

    // Fresh connection: leave the panel in normal 2D until a session starts
    this._reset2DIfIdle();

    return this._getDeviceInfo();
  }

  async _sendCommand(cmd, value = 0) {
    const devices = this._allDevices || (this.device ? [this.device] : []);
    const frame = new Uint8Array(64);
    frame[0] = 0x66;
    frame[1] = cmd;
    frame[2] = value;

    let sent = false;
    for (const device of devices) {
      // (Re)open lazily: after a replug or a failed open during connect, the
      // handles can be closed even though the device object is still
      // authorized - without this the command would be silently dropped
      if (!device.opened) {
        try {
          await device.open();
        } catch (e) {
          continue;
        }
      }
      // Try the documented layout first (report ID 0), then alternatives for
      // hosts/devices that number their reports
      for (const reportId of this._outputReportIds) {
        try {
          await device.sendReport(reportId, frame);
          sent = true;
          if (reportId !== 0x00) {
            console.warn(`RayNeo: command 0x${cmd.toString(16)} needed report ID 0x${reportId.toString(16)} - please report this`);
          }
          break;
        } catch (e) {
          debugLog(`RayNeo: sendReport(id 0x${reportId.toString(16)}, 0x${cmd.toString(16)}) failed:`, e.message);
        }
      }
    }
    if (!sent && devices.length > 0) {
      console.warn(`RayNeo: could not send command 0x${cmd.toString(16)} to any device/report ID`);
    }
    return sent;
  }

  async _startIMU() {
    console.log('RayNeo: Sending IMU enable command (0x66 0x01)...');
    this._imuOn = true;
    await this._sendCommand(0x01); // IMU on
    // (Re)connect can reset the display controller: re-assert the mode a live
    // session put the panel in (only set when a session requested stereo and
    // the glasses have not dropped off since)
    if (this._stereoOn) {
      this._sendCommand(0x06);
    }
    this._lastReportTime = performance.now();

    // Watchdog: the stream stops after the glasses sleep; ask again.
    if (this._watchdog) clearInterval(this._watchdog);
    this._watchdog = setInterval(() => {
      if (!this.connected) return;
      if (performance.now() - this._lastReportTime > 1500) {
        this._sendCommand(0x01);
        // A wake cycle may have reset the display mode too
        if (this._stereoOn) {
          this._sendCommand(0x06);
        }
        if (!this._watchWarned) {
          this._watchWarned = true;
          console.warn('RayNeo: no IMU data received after connecting - re-sending IMU enable. ' +
            'If this keeps appearing, check the "unparsed report" console warnings for the real frame format.');
        }
      }
    }, 2000);
  }

  async checkExistingConnection() {
    if (!RayNeoHID.isSupported()) return false;

    debugLog('RayNeo: Checking for existing connections...');
    const devices = await navigator.hid.getDevices();
    const rayneoDevices = devices.filter(d => this._matches(d));

    if (rayneoDevices.length === 0) {
      debugLog('RayNeo: No matching devices found');
      return false;
    }

    console.log(`RayNeo: Found ${rayneoDevices.length} RayNeo device(s), opening all...`);

    for (let i = 0; i < rayneoDevices.length; i++) {
      const device = rayneoDevices[i];
      try {
        if (!device.opened) {
          await device.open();
        }
        device.addEventListener('inputreport', (event) => this._handleInputReport(event, i));
      } catch (e) {
        console.warn(`RayNeo: Failed to open device ${i + 1}:`, e.message);
      }
    }

    this.device = rayneoDevices[0];
    this._allDevices = rayneoDevices;
    this.connected = true;

    await this._startIMU();

    window.postMessage({
      type: 'RAYNEO_DEVICE_CONNECTED',
      deviceInfo: this._getDeviceInfo()
    }, '*');

    // Fresh connection: leave the panel in normal 2D until a session starts
    this._reset2DIfIdle();

    return true;
  }

  async disconnect() {
    if (this._watchdog) {
      clearInterval(this._watchdog);
      this._watchdog = null;
    }
    if (this._allDevices) {
      try {
        await this._sendCommand(0x02); // IMU off
      } catch (e) { /* ignore */ }
      for (const device of this._allDevices) {
        if (device && device.opened) {
          try {
            await device.close();
          } catch (e) {
            console.warn('RayNeo: Error closing device:', e);
          }
        }
      }
    }
    // Clear state and notify the extension (popup status, sites)
    this._markDisconnected();
  }

  // Display helpers ----------------------------------------------------------

  /** Put the glasses in 3840x1080 side-by-side mode (needed for stereo WebXR
   *  content to appear correctly). Pass false to switch back to 2D.
   *
   *  The mode command is re-asserted a few times over ~1.5 s: right after a
   *  fresh connection the display controller may still be initializing (or
   *  the glasses just woke from sleep) and a single command can be missed.
   *  Re-sending the same mode is harmless, and a later setStereo() call
   *  cancels pending re-asserts - so a session end always wins. */
  async setStereo(on) {
    // "Auto mode switch" disabled in the popup: the user controls the panel
    // mode themselves (e.g. with the glasses' own controls). Explicit manual
    // calls (console __rayneoRestore2D) still work.
    if (window.__rayneoAutoModeSwitch === false) return;

    this._stereoOn = !!on;
    for (const t of this._stereoTimers) clearTimeout(t);
    this._stereoTimers = [];

    const cmd = on ? 0x06 : 0x07;
    const reassert = () => {
      if (this.connected) this._sendCommand(cmd);
    };

    await this._sendCommand(cmd);
    for (const delay of [250, 700, 1500, 2500]) {
      this._stereoTimers.push(setTimeout(reassert, delay));
    }
  }

  /** Panel refresh rate: 60 or 120 Hz. */
  async setPanelRate(rate) {
    await this._sendCommand(rate >= 120 ? 0x21 : 0x20);
  }

  // Input report handling ----------------------------------------------------

  _handleInputReport(event, deviceIndex = 0) {
    const dv = event.data;
    const bytes = new Uint8Array(dv.buffer, dv.byteOffset, dv.byteLength);
    this._lastReportTime = performance.now();
    this._reportCount++;

    if (bytes.length < 48) return;

    // Locate the 0x99 frame header. Hosts and firmwares disagree about
    // whether it lives in the report ID or the data, so try all layouts:
    //   a) data[0]=0x99, data[1]=type            (header in data)
    //   b) data[1]=0x99, data[2]=type            (padded)
    //   c) reportId=0x99, data[0]=type           (header consumed as report ID)
    // Payload offsets are relative to the header (accel = header+4).
    let hdrIdx = -99;
    if (bytes[0] === 0x99) hdrIdx = 0;
    else if (bytes[1] === 0x99) hdrIdx = 1;
    else if (event.reportId === 0x99 && bytes[0] === 0x65) hdrIdx = -1;

    if (hdrIdx > -99) {
      const type = hdrIdx >= 0 ? bytes[hdrIdx + 1] : bytes[0];
      if (type === 0x65) {
        this._handleImuFrame(dv, hdrIdx + 4);
      } else if (type === 0xc8) {
        this._handleAck(bytes, hdrIdx);
      }
      return;
    }

    // Unrecognized frame: log the first few so we can identify the real format
    this._unparsedLogged++;
    const hex = Array.from(bytes.slice(0, 24)).map(b => b.toString(16).padStart(2, '0')).join(' ');
    this._lastUnparsedHex = `reportId 0x${event.reportId.toString(16)}: ${hex}`;
    if (this._unparsedLogged <= 10) {
      console.warn(`RayNeo: unparsed report (device ${deviceIndex}, ${this._lastUnparsedHex})`);
    }
  }

  _handleImuFrame(dv, base) {
    // base = offset of the accelerometer float[3] (header+4 per protocol)
    this._imuCount++;
    if (this._imuCount === 1) {
      console.log('RayNeo: IMU stream started - gyro bias calibration begins, hold still ~1.5 s');
    }
    const acc = [dv.getFloat32(base, true), dv.getFloat32(base + 4, true), dv.getFloat32(base + 8, true)];
    const gyroDeg = [dv.getFloat32(base + 12, true), dv.getFloat32(base + 16, true), dv.getFloat32(base + 20, true)];
    const temperature = dv.getFloat32(base + 24, true);
    const tick = dv.getUint32(base + 36, true);

    this._lastReportTime = performance.now();

    const gyro = gyroDeg.map(g => g * DEG); // deg/s -> rad/s
    this._fuse(acc, gyro, tick);

    if (!this._logCount) this._logCount = 0;
    this._logCount++;
    if (RAYNEO_DEBUG && (this._logCount <= 5 || this._logCount % 500 === 0)) {
      console.log('RayNeo IMU: acc', acc.map(v => v.toFixed(2)), 'gyro°/s', gyroDeg.map(v => v.toFixed(2)),
        'temp', temperature.toFixed(1), 'q', this.quaternion);
    }
  }

  _handleAck(bytes, off) {
    // Ack frames; byte off+8 carries sleep (0x41) / wake (0x42) notices on
    // some firmware. On wake, restart the IMU stream and re-assert the
    // display mode (a wake cycle can reset the display controller).
    const b = bytes[off + 8];
    if (b === 0x42 && !this._imuOn) {
      debugLog('RayNeo: glasses woke up, restarting IMU');
      this._imuOn = true;
      this._sendCommand(0x01);
      if (this._stereoOn) {
        this._sendCommand(0x06);
      }
    } else if (b === 0x41) {
      this._imuOn = false;
    }
  }

  // ---------------------------------------------------------------------------
  // Fusion: Mahony complementary filter + gyro-bias calibration
  // ---------------------------------------------------------------------------

  _fuse(acc, gyro, tick) {
    if (!this._initialized) {
      const an = Math.hypot(acc[0], acc[1], acc[2]);
      if (an < 1) return;
      // Initialize orientation from gravity: map measured "up" onto world +y
      this._q = quatFromTo([acc[0] / an, acc[1] / an, acc[2] / an], [0, 1, 0]);
      this._initialized = true;
      this._lastTick = tick;
      this._lpAcc = [...acc];
      this._lpGyro = [...gyro];
      return;
    }

    if (tick === this._lastTick) return; // glasses re-send the last sample when idle
    const dt = ((tick - this._lastTick) >>> 0) * 1e-4;
    this._lastTick = tick;
    if (dt <= 0 || dt > 0.05) return; // bad/first dt after a stall

    // --- Startup bias calibration: mean of still samples --------------------
    if (!this._calibrated) {
      const moving = Math.max(Math.abs(gyro[0]), Math.abs(gyro[1]), Math.abs(gyro[2])) > RayNeoHID.CALIB_MAX_GYRO;
      if (moving) {
        this._calCount = 0;
        this._calSum = [0, 0, 0];
      } else {
        for (let i = 0; i < 3; i++) this._calSum[i] += gyro[i];
        this._calCount++;
        if (this._calCount >= RayNeoHID.CALIB_SAMPLES) {
          this._bias = this._calSum.map(s => s / this._calCount);
          this._calibrated = true;
          console.log('RayNeo: gyro bias calibrated', this._bias.map(b => (b / DEG).toFixed(3) + '°/s'));
          this.recenter(); // define "forward" once we're stable
        }
      }
    }

    // --- Low-pass for rest detection (VQF-style) -----------------------------
    const k = Math.min(dt / 0.5, 1);
    for (let i = 0; i < 3; i++) {
      this._lpGyro[i] += (gyro[i] - this._lpGyro[i]) * k;
      this._lpAcc[i] += (acc[i] - this._lpAcc[i]) * k;
    }

    // At rest: gyro matches its own low-pass, the low-passed gyro is close to
    // the current bias, and the accelerometer is steady. Then the low-passed
    // gyro IS the bias (drift correction).
    const gyroJitter = Math.hypot(gyro[0] - this._lpGyro[0], gyro[1] - this._lpGyro[1], gyro[2] - this._lpGyro[2]);
    const accJitter = Math.hypot(acc[0] - this._lpAcc[0], acc[1] - this._lpAcc[1], acc[2] - this._lpAcc[2]);
    let corrMax = 0;
    for (let i = 0; i < 3; i++) corrMax = Math.max(corrMax, Math.abs(this._lpGyro[i] - this._bias[i]));
    const resting = gyroJitter < 2 * DEG && corrMax < 0.6 * DEG && accJitter < 0.5;

    this._stillTime = resting ? this._stillTime + dt : 0;
    if (this._stillTime > 1.5) {
      const kb = Math.min(dt / 3, 1);
      for (let i = 0; i < 3; i++) this._bias[i] += (this._lpGyro[i] - this._bias[i]) * kb;
    }

    // --- Mahony correction ---------------------------------------------------
    const w = [gyro[0] - this._bias[0], gyro[1] - this._bias[1], gyro[2] - this._bias[2]];
    let wc = [w[0], w[1], w[2]];
    const an = Math.hypot(acc[0], acc[1], acc[2]);

    if (an > 7 && an < 12.5) {
      const measuredUp = [acc[0] / an, acc[1] / an, acc[2] / an];
      const estimatedUp = quatRotate(quatConj(this._q), [0, 1, 0]); // world up in device frame
      const err = [
        measuredUp[1] * estimatedUp[2] - measuredUp[2] * estimatedUp[1],
        measuredUp[2] * estimatedUp[0] - measuredUp[0] * estimatedUp[2],
        measuredUp[0] * estimatedUp[1] - measuredUp[1] * estimatedUp[0]
      ];
      const errMag = Math.hypot(err[0], err[1], err[2]);
      const errAngle = Math.asin(Math.min(1, errMag));

      let accept = (Math.abs(an - 9.81) < 1.5 && errAngle < 10 * DEG) || this._rejectTime > 3;
      let gain = RayNeoHID.KP / (1 + Math.hypot(w[0], w[1], w[2]) / 2);

      if (accept) {
        // After a long rejection, converge fast once (x-io Fusion style)
        if (this._rejectTime > 3) gain *= 5;
        this._rejectTime = 0;
        wc = [wc[0] + gain * err[0], wc[1] + gain * err[1], wc[2] + gain * err[2]];
      } else {
        // Fast head turns leak centripetal acceleration into the reading
        this._rejectTime += dt;
      }
    }

    // Integrate: q = q * quat(wc * dt)   (body-frame angular velocity)
    const wMag = Math.hypot(wc[0], wc[1], wc[2]);
    const angle = wMag * dt;
    if (angle > 1e-12) {
      this._q = quatNorm(quatMul(this._q, quatAxisAngle(wc, angle)));
    }

    // --- Pose with yaw-only recentering --------------------------------------
    if (this._yawRef) {
      this.quaternion = quatNorm(quatMul(quatConj(this._yawRef), this._q));
    } else {
      this.quaternion = this._q;
    }

    this._notifyCallbacks();
  }

  recenter() {
    // Reset yaw to the current facing direction; keep pitch and roll absolute.
    const f = quatRotate(this._q, [0, 0, -1]); // forward in world frame
    const yaw = Math.atan2(-f[0], -f[2]);
    this._yawRef = quatAxisAngle([0, 1, 0], yaw);
    if (this._initialized) {
      this.quaternion = quatNorm(quatMul(quatConj(this._yawRef), this._q));
    }
  }

  _getDeviceInfo() {
    if (!this.device) return null;
    return {
      model: `RayNeo Air (${(this.device.productName || 'AR glasses')})`,
      vendorId: this.device.vendorId,
      productId: this.device.productId,
      productName: this.device.productName
    };
  }

  onOrientationChange(callback) {
    this.callbacks.add(callback);
    return () => this.callbacks.delete(callback);
  }

  _notifyCallbacks() {
    const q = this.quaternion;
    this.callbacks.forEach(cb => cb(q));

    // Also notify extension for cross-tab sync
    window.postMessage({
      type: 'RAYNEO_ORIENTATION_UPDATE',
      orientation: q
    }, '*');
  }

  getQuaternion() {
    return { ...this.quaternion };
  }

  getQuaternionArray() {
    return [this.quaternion.x, this.quaternion.y, this.quaternion.z, this.quaternion.w];
  }

  /** Snapshot of the connection/stream state for debugging */
  getDiagnostics() {
    return {
      connected: this.connected,
      reportsReceived: this._reportCount,
      imuFramesParsed: this._imuCount,
      fusionInitialized: this._initialized,
      biasCalibrated: this._calibrated,
      lastUnparsedReport: this._lastUnparsedHex,
      quaternion: this.quaternion
    };
  }
}

// Restore the glasses to normal 2D viewing from any page that holds the
// persistent WebHID grant (the site the glasses were connected on). Used by
// the extension after the tab that was playing VR content was closed: that
// page's session is destroyed without end() running, so nothing switched the
// panel out of side-by-side mode.
async function restoreRayNeo2D() {
  if (!RayNeoHID.isSupported()) return false;

  let granted;
  try {
    granted = await navigator.hid.getDevices();
  } catch (e) {
    return false;
  }

  let restored = false;
  for (const device of granted) {
    if (!RAYNEO_VIDS.includes(device.vendorId) || device.productId !== RAYNEO_PID) continue;
    try {
      if (!device.opened) await device.open();
      const frame = new Uint8Array(64);
      frame[0] = 0x66;
      frame[1] = 0x07; // 2D display mode
      frame[2] = 0;
      let sent = false;
      for (const reportId of [0x00, 0x66]) {
        try {
          await device.sendReport(reportId, frame);
          sent = true;
          break;
        } catch (e) { /* try the next report id */ }
      }
      if (sent) restored = true;
      try { await device.close(); } catch (e) { /* noop */ }
    } catch (e) {
      // Cannot open (another page holds it open, glasses absent, ...)
    }
  }
  if (restored) {
    console.log('RayNeo: display restored to normal 2D mode');
  }
  return restored;
}

// Make available globally in page context
window.RayNeoHID = RayNeoHID;
window.__rayneoRestore2D = restoreRayNeo2D;

/**
 * RayNeo WebXR Polyfill
 * Makes RayNeo glasses appear as a WebXR device
 */

// Debug flag - set to true for verbose logging

function debugLog(...args) {
  if (RAYNEO_DEBUG) console.log(...args);
}


// ------------------------------------------------- VR presentation helpers
// While an immersive session is live the screen is a headset mirror: the
// mouse cursor and the site's own player chrome only distract. These
// helpers hide the cursor globally, optionally hide site-matched elements,
// and focus/fullscreen the site's XR canvas.

function vrPresentationApply(on) {
  let sel = '';
  try { sel = localStorage.getItem('rayneo-hide-ui') || ''; } catch (e) { /* noop */ }
  let st = document.getElementById('rayneo-vr-presentation');
  if (!on) {
    if (st) st.remove();
    return;
  }
  if (!st) {
    st = document.createElement('style');
    st.id = 'rayneo-vr-presentation';
    (document.head || document.documentElement).appendChild(st);
  }
  st.textContent = '* { cursor: none !important; }'
    + (sel ? sel + ' { display: none !important; }' : '');
}

// Persist (per-site) a CSS selector to hide while VR is active.
// Usage: __rayneoHideUI('.player-controls, .site-header')  — pass no
// argument to clear.
window.__rayneoHideUI = function (selector) {
  try {
    if (selector) {
      localStorage.setItem('rayneo-hide-ui', selector);
      console.log('RayNeo: will hide "' + selector + '" on this site while VR is active (applies to new sessions; run __rayneoDiag style reload to test)');
    } else {
      localStorage.removeItem('rayneo-hide-ui');
      console.log('RayNeo: per-site UI hiding cleared');
    }
  } catch (e) {
    console.warn('RayNeo: localStorage unavailable:', e);
  }
};

// Fullscreen the largest visible canvas (the site's XR renderer) so the
// browser chrome and page UI drop away. Also runs automatically on session
// start when the entry click's user-activation is still valid.
window.__rayneoVRFocus = function () {
  const canvases = [...document.querySelectorAll('canvas')]
    .filter(c => c.offsetWidth && c.offsetHeight)
    .sort((a, b) => (b.offsetWidth * b.offsetHeight) - (a.offsetWidth * a.offsetHeight));
  const target = canvases[0] || document.documentElement;
  if (target.requestFullscreen) {
    return target.requestFullscreen().catch(e => {
      console.log('RayNeo: fullscreen rejected:', e && e.message);
    });
  }
};

// After the SBS command the OS needs a moment to re-arrange the glasses
// display (1920x1080 -> 3840x1080). If the session - and with it the
// fullscreen - starts during that window, it opens as a 1920-wide screen and
// the stereo image comes up squeezed. Wait until the screen geometry reflects
// the new mode before resolving; the site's requestSession() (and everything
// it does afterwards, including its own fullscreen) only continues then.
function settleDisplayAfterModeChange(baselineWidth) {
  // Already in a wide arrangement (re-entering VR, or the glasses always
  // report the wide mode): nothing to wait for
  if (screen.width >= 3000) return Promise.resolve();

  const CAP_MS = 3000;    // observed transitions take up to ~2-3 s
  const start = performance.now();

  function poll() {
    // Mode change observed: give the compositor a beat to apply the new
    // geometry, then let the session start
    if (screen.width !== baselineWidth && screen.width > 0) {
      return new Promise((resolve) => setTimeout(resolve, 300));
    }
    if (performance.now() - start >= CAP_MS) {
      // Cannot observe the change (e.g. the window sits on another screen).
      // Don't stall VR entry forever - the panel command itself has had the
      // full cap to take effect by now.
      return Promise.resolve();
    }
    return new Promise((resolve) => setTimeout(resolve, 100)).then(poll);
  }

  return poll();
}

// While the glasses' display transition is pending (SBS command sent, OS
// still re-arranging), players that fullscreen themselves on VR entry would
// open a 1920-wide fullscreen and render the stereo image squeezed. Defer
// their requestFullscreen() calls until the transition completes.
let displaySettling = false;
let displaySettledOnce = false;
let settlingBaselineWidth = 0;

class RayNeoXRSession {
  constructor(mode, rayneo) {
    this.mode = mode;
    this.rayneo = rayneo;
    this.ended = false;
    this.renderState = {
      baseLayer: null,
      depthFar: 1000,
      depthNear: 0.1,
      inlineVerticalFieldOfView: Math.PI / 2
    };
    this.inputSources = [];
    this._frameCallbacks = [];
    this._animationFrameId = null;
    this._referenceSpaces = new Map();
    this._lastFrameTime = 0;

    // Set isImmersive as a data property (some apps try to set it)
    this.isImmersive = (mode === 'immersive-vr' || mode === 'immersive-ar');

    // Immersive sessions present side-by-side stereo to the glasses: switch
    // the panel into SBS mode automatically, and back to 2D when the session
    // ends (the site's normal playback must not stay split).
    if (this.isImmersive && this.rayneo.connected) {
      this.rayneo.setStereo(true).catch(() => {});
      // Register this tab as "presenting VR content" with the extension: if
      // the tab is closed without the session ending, the extension switches
      // the glasses back to 2D (see background.js tab-close handling).
      window.postMessage({ type: 'RAYNEO_VR_SESSION_STARTED' }, '*');
    }

    // Headset-mirror presentation: hide cursor/UI, try to fullscreen the
    // site's XR canvas (works when the session start still carries the
    // click's user activation; otherwise run __rayneoVRFocus() manually)
    if (this.isImmersive) {
      vrPresentationApply(true);
      window.__rayneoVRFocus();
    }

    // Start frame loop
    this._startFrameLoop();
  }

  get visibilityState() {
    return 'visible';
  }

  get frameRate() {
    return 60; // RayNeo Air 4 Pro native SBS refresh rate
  }

  get supportedFrameRates() {
    return Float32Array.from([60, 120]);
  }

  updateTargetFrameRate(rate) {
    // Accept and ignore: we always present at the panel's native rate
    return Promise.resolve();
  }

  get environmentBlendMode() {
    return 'opaque';
  }

  get interactionMode() {
    return 'world-space';
  }

  addEventListener(type, listener) {
    // Basic event handling
    if (!this._listeners) this._listeners = {};
    if (!this._listeners[type]) this._listeners[type] = [];
    this._listeners[type].push(listener);
  }

  removeEventListener(type, listener) {
    if (!this._listeners || !this._listeners[type]) return;
    const idx = this._listeners[type].indexOf(listener);
    if (idx !== -1) this._listeners[type].splice(idx, 1);
  }

  _dispatchEvent(type, event) {
    if (!this._listeners || !this._listeners[type]) return;
    this._listeners[type].forEach(l => l(event));
  }

  async requestReferenceSpace(type) {
    // One-time visibility: which spaces does the app use?
    if (!this._rsTypesLogged) this._rsTypesLogged = new Set();
    if (!this._rsTypesLogged.has(type)) {
      this._rsTypesLogged.add(type);
      console.log('[RayNeo polyfill] requestReferenceSpace("' + type + '")');
    }
    if (this._referenceSpaces.has(type)) {
      return this._referenceSpaces.get(type);
    }

    const space = new RayNeoXRReferenceSpace(type, this.rayneo);
    this._referenceSpaces.set(type, space);
    return space;
  }

  updateRenderState(newState) {
    if (!this._renderStateLogged) {
      this._renderStateLogged = true;
      const keys = Object.keys(newState || {});
      console.log('[RayNeo polyfill] updateRenderState:', keys.length ? keys.join(', ') : '(empty)');
    }
    Object.assign(this.renderState, newState);
  }

  requestAnimationFrame(callback) {
    const handle = this._frameCallbacks.length;
    this._frameCallbacks.push(callback);
    return handle;
  }

  cancelAnimationFrame(handle) {
    if (handle < this._frameCallbacks.length) {
      this._frameCallbacks[handle] = null;
    }
  }

  _startFrameLoop() {
    const loop = (timestamp) => {
      if (this.ended) return;

      this._animationFrameId = requestAnimationFrame(loop);

      // Keep the drawing buffer at the native SBS size: sites may resize
      // their canvas mid-session from stale window geometry (e.g. on the
      // fullscreen resize event), which would shrink each eye back to a
      // quarter of the panel
      const layer = this._layer;
      if (layer) {
        const canvas = layer.context.canvas;
        if (canvas.width !== layer._framebufferWidth || canvas.height !== layer._framebufferHeight) {
          try {
            canvas.width = layer._framebufferWidth;
            canvas.height = layer._framebufferHeight;
          } catch (e) { /* site owns the canvas; keep its size */ }
        }
      }

      // Create XRFrame
      const frame = new RayNeoXRFrame(this, timestamp);

      // Call all registered callbacks
      const callbacks = this._frameCallbacks.slice();
      this._frameCallbacks = [];

      callbacks.forEach(cb => {
        if (cb) cb(timestamp, frame);
      });

      this._lastFrameTime = timestamp;
    };

    this._animationFrameId = requestAnimationFrame(loop);
  }

  async end() {
    this.ended = true;
    if (this._animationFrameId) {
      cancelAnimationFrame(this._animationFrameId);
    }
    // Restore the glasses' panel to 2D for normal desktop use
    if (this.isImmersive && this.rayneo.connected) {
      try { await this.rayneo.setStereo(false); } catch (e) { /* noop */ }
    }
    // Leave presentation mode: restore cursor/UI and browser chrome
    if (this.isImmersive) {
      vrPresentationApply(false);
      if (document.fullscreenElement) document.exitFullscreen().catch(() => {});
      // Normal exit path: the panel is back in 2D, so the extension no longer
      // needs to watch this tab for a close-while-in-SBS situation
      window.postMessage({ type: 'RAYNEO_VR_SESSION_ENDED' }, '*');
    }
    this._dispatchEvent('end', { session: this });
  }
}

class RayNeoXRFrame {
  constructor(session, timestamp) {
    this.session = session;
    this._timestamp = timestamp;
  }

  getViewerPose(referenceSpace) {
    if (!referenceSpace) return null;
    this.session._frameCount = (this.session._frameCount || 0) + 1;
    if (!this.session._viewerPoseLogged) {
      this.session._viewerPoseLogged = true;
      console.log('[RayNeo polyfill] getViewerPose called - tracking is flowing to the app');
    }
    return new RayNeoXRViewerPose(this.session, referenceSpace);
  }

  getPose(space, baseSpace) {
    // Return identity pose for now
    return {
      transform: new RayNeoXRRigidTransform()
    };
  }
}

class RayNeoXRViewerPose {
  constructor(session, referenceSpace) {
    this.session = session;
    this.referenceSpace = referenceSpace;

    // Get quaternion from RayNeo device
    const q = session.rayneo.connected ? session.rayneo.getQuaternion() : { x: 0, y: 0, z: 0, w: 1 };

    // Debug: Log quaternion periodically
    if (!RayNeoXRViewerPose._lastLog || (Date.now() - RayNeoXRViewerPose._lastLog > 1000)) {
      debugLog('RayNeoXRViewerPose: quaternion', q, 'connected:', session.rayneo.connected);
      RayNeoXRViewerPose._lastLog = Date.now();
    }

    this.transform = new RayNeoXRRigidTransform(
      { x: 0, y: 0, z: 0, w: 1 },
      q
    );

    // For stereo, create two views
    if (session.mode === 'immersive-vr') {
      this.views = [
        new RayNeoXRView('left', session),
        new RayNeoXRView('right', session)
      ];
    } else {
      this.views = [new RayNeoXRView('none', session)];
    }
  }

  get emulatedPosition() {
    return true; // Position is emulated (3DoF only)
  }
}

class RayNeoXRView {
  constructor(eye, session) {
    this.eye = eye;
    this.session = session;

    // RayNeo Air 4 Pro FOV is approximately 45 degrees
    const fov = 45 * Math.PI / 180;
    const aspect = 16 / 9;

    this.projectionMatrix = new Float32Array(16);
    this._makePerspective(this.projectionMatrix, fov, aspect, 0.1, 1000);

    // View transform includes eye offset for stereo
    const q = session.rayneo.connected ? session.rayneo.getQuaternion() : { x: 0, y: 0, z: 0, w: 1 };
    const eyeOffset = eye === 'left' ? -0.032 : (eye === 'right' ? 0.032 : 0);

    this.transform = new RayNeoXRRigidTransform(
      { x: eyeOffset, y: 0, z: 0, w: 1 },
      q
    );

    // recommendedViewportScale is used by some apps
    this.recommendedViewportScale = 1.0;
  }

  _makePerspective(out, fov, aspect, near, far) {
    const f = 1.0 / Math.tan(fov / 2);
    const nf = 1 / (near - far);

    out[0] = f / aspect;
    out[1] = 0;
    out[2] = 0;
    out[3] = 0;
    out[4] = 0;
    out[5] = f;
    out[6] = 0;
    out[7] = 0;
    out[8] = 0;
    out[9] = 0;
    out[10] = (far + near) * nf;
    out[11] = -1;
    out[12] = 0;
    out[13] = 0;
    out[14] = 2 * far * near * nf;
    out[15] = 0;
  }
}

class RayNeoXRReferenceSpace {
  constructor(type, rayneo) {
    this.type = type;
    this.rayneo = rayneo;
  }

  getOffsetReferenceSpace(originOffset) {
    return new RayNeoXRReferenceSpace(this.type, this.rayneo);
  }

  addEventListener() {}
  removeEventListener() {}
}

class RayNeoXRRigidTransform {
  constructor(position = { x: 0, y: 0, z: 0, w: 1 }, orientation = { x: 0, y: 0, z: 0, w: 1 }, isInverse = false) {
    this.position = new DOMPointReadOnly(position.x, position.y, position.z, position.w || 1);
    this.orientation = new DOMPointReadOnly(orientation.x, orientation.y, orientation.z, orientation.w);

    // Build 4x4 transformation matrix
    this.matrix = new Float32Array(16);
    this._buildMatrix();

    // Compute inverse (but don't recurse infinitely)
    if (!isInverse) {
      this._inverse = null; // Lazy compute
    } else {
      this._inverse = null; // Inverse of inverse would be the original, but we don't need it
    }
    this._isInverse = isInverse;
  }

  get inverse() {
    if (this._inverse === null && !this._isInverse) {
      // Compute the inverse transform
      // Inverse rotation = conjugate quaternion
      const invOrientation = {
        x: -this.orientation.x,
        y: -this.orientation.y,
        z: -this.orientation.z,
        w: this.orientation.w
      };

      // Inverse position = -R^T * position
      // Apply inverse rotation to negated position
      const p = this.position;
      const q = invOrientation;

      // Rotate -position by inverse quaternion
      const px = -p.x, py = -p.y, pz = -p.z;

      // Quaternion rotation: q * p * q^-1
      // Since q is already the inverse rotation, we just apply it
      const qx = q.x, qy = q.y, qz = q.z, qw = q.w;

      // p' = q * (px, py, pz, 0) * q^-1
      // Simplified quaternion-vector multiplication
      const ix = qw * px + qy * pz - qz * py;
      const iy = qw * py + qz * px - qx * pz;
      const iz = qw * pz + qx * py - qy * px;
      const iw = -qx * px - qy * py - qz * pz;

      const invPx = ix * qw + iw * -qx + iy * -qz - iz * -qy;
      const invPy = iy * qw + iw * -qy + iz * -qx - ix * -qz;
      const invPz = iz * qw + iw * -qz + ix * -qy - iy * -qx;

      this._inverse = new RayNeoXRRigidTransform(
        { x: invPx, y: invPy, z: invPz, w: 1 },
        invOrientation,
        true // Mark as inverse to prevent recursion
      );
    }
    return this._inverse;
  }

  _buildMatrix() {
    const q = this.orientation;
    const p = this.position;

    // Quaternion to rotation matrix
    const x2 = q.x + q.x;
    const y2 = q.y + q.y;
    const z2 = q.z + q.z;

    const xx = q.x * x2;
    const xy = q.x * y2;
    const xz = q.x * z2;
    const yy = q.y * y2;
    const yz = q.y * z2;
    const zz = q.z * z2;
    const wx = q.w * x2;
    const wy = q.w * y2;
    const wz = q.w * z2;

    this.matrix[0] = 1 - (yy + zz);
    this.matrix[1] = xy + wz;
    this.matrix[2] = xz - wy;
    this.matrix[3] = 0;
    this.matrix[4] = xy - wz;
    this.matrix[5] = 1 - (xx + zz);
    this.matrix[6] = yz + wx;
    this.matrix[7] = 0;
    this.matrix[8] = xz + wy;
    this.matrix[9] = yz - wx;
    this.matrix[10] = 1 - (xx + yy);
    this.matrix[11] = 0;
    this.matrix[12] = p.x;
    this.matrix[13] = p.y;
    this.matrix[14] = p.z;
    this.matrix[15] = 1;
  }
}

/**
 * XRWebGLLayer polyfill for RayNeo sessions
 */
// Native SBS panel layout of the RayNeo Air glasses: 3840x1080 total,
// 1920x1080 per eye. Immersive sessions always render side-by-side stereo,
// so the drawing buffer must match this regardless of what resolution the
// OS currently drives the panel at (the display mode can lag the panel
// switch by a second or more).
const SBS_FRAMEBUFFER_WIDTH = 3840;
const SBS_FRAMEBUFFER_HEIGHT = 1080;

class RayNeoXRWebGLLayer {
  constructor(session, context, options = {}) {
    this.session = session;
    this.context = context;
    this._options = options;

    // Get canvas dimensions
    const canvas = context.canvas;

    // Immersive session: the site sizes its canvas from window geometry that
    // can be stale (captured before the display switched to the wide/SBS
    // arrangement, or while the window was still on another screen) - the
    // stereo image then renders 1920-wide and each eye ends up squeezed into
    // a quarter of the panel. Force the drawing buffer to the panel's native
    // SBS size and keep it enforced for the session's lifetime (frame loop).
    if (session.isImmersive) {
      try {
        canvas.width = SBS_FRAMEBUFFER_WIDTH;
        canvas.height = SBS_FRAMEBUFFER_HEIGHT;
      } catch (e) { /* site owns the canvas; keep its size */ }
      // Make the layer reachable from the frame loop for re-enforcement
      session._layer = this;
    }

    this._framebufferWidth = canvas.width;
    this._framebufferHeight = canvas.height;

    // Store original framebuffer (null = default)
    this._framebuffer = null;

    // Mark session with this layer
    if (session.updateRenderState) {
      // Will be called by the app
    }

    debugLog('RayNeoXRWebGLLayer created:', this._framebufferWidth, 'x', this._framebufferHeight);
  }

  get framebuffer() {
    return this._framebuffer;
  }

  get framebufferWidth() {
    return this._framebufferWidth;
  }

  get framebufferHeight() {
    return this._framebufferHeight;
  }

  get antialias() {
    return this._options.antialias !== false;
  }

  get ignoreDepthValues() {
    return this._options.ignoreDepthValues || false;
  }

  getViewport(view) {
    // For stereo, split viewport left/right
    const width = this._framebufferWidth;
    const height = this._framebufferHeight;

    if (view.eye === 'left') {
      return { x: 0, y: 0, width: width / 2, height: height };
    } else if (view.eye === 'right') {
      return { x: width / 2, y: 0, width: width / 2, height: height };
    } else {
      // Mono view
      return { x: 0, y: 0, width: width, height: height };
    }
  }
}

class RayNeoXRSystem {
  constructor(rayneo) {
    this.rayneo = rayneo;
    this._sessions = [];
  }

  async isSessionSupported(mode) {
    // Disabled via popup toggle -> pretend XR isn't available
    if (window.__rayneoDisabled) {
      return mode === 'inline' && originalXR ? originalXR.isSessionSupported(mode) : false;
    }
    // Support inline and immersive-vr modes
    return mode === 'inline' || mode === 'immersive-vr';
  }

  async requestSession(mode, options = {}) {
    if (window.__rayneoDisabled) {
      throw new DOMException('RayNeo WebXR is disabled', 'InvalidStateError');
    }
    debugLog('RayNeoXRSystem: requestSession called', mode, 'connected:', this.rayneo.connected);

    if (mode === 'immersive-vr' && !this.rayneo.connected) {
      // First try devices the user already authorized (no gesture needed),
      // then fall back to the full WebHID permission flow
      try {
        await this.rayneo.checkExistingConnection();
      } catch (e) { /* fall through */ }

      if (!this.rayneo.connected) {
        debugLog('RayNeoXRSystem: Attempting to connect to RayNeo glasses...');
        try {
          await this.rayneo.connect();
          debugLog('RayNeoXRSystem: Connected successfully');
        } catch (e) {
          debugLog('RayNeoXRSystem: Connection failed:', e);
          throw new DOMException('Failed to connect to RayNeo glasses: ' + e.message, 'NotSupportedError');
        }
      }
    }

    const session = new RayNeoXRSession(mode, this.rayneo);
    this._sessions.push(session);
    const feats = options && options.optionalFeatures ? options.optionalFeatures.join(',') : '';
    console.log(`[RayNeo polyfill] session created (${mode})` + (feats ? ` optionalFeatures: ${feats}` : ''));
    return session;
  }
}

// Global RayNeo instance
let globalRayNeo = null;
let globalXRSystem = null;

function initRayNeoWebXR() {
  if (globalRayNeo) return globalXRSystem;

  globalRayNeo = new RayNeoHID();
  globalXRSystem = new RayNeoXRSystem(globalRayNeo);

  // Check for existing connection
  globalRayNeo.checkExistingConnection().catch(() => {});

  // Store original XR if exists
  const originalXR = navigator.xr;

  // Create proxy XR system

  // Sites whose players must see "VR available" even before the glasses are
  // connected: they gate their entire VR UI on that check and never enter VR
  // on their own. On other sites we must NOT advertise VR until the glasses
  // are connected — some players (e.g. pornhub) detect a "headset" and
  // auto-request a WebXR session, which hijacks/stalls their normal player.
  const ALWAYS_OFFER_VR_HOSTS = ['deovr.com'];
  const hostAllowlisted = ALWAYS_OFFER_VR_HOSTS.some(
    h => location.hostname === h || location.hostname.endsWith('.' + h)
  );
  // Per-site opt-in set by the user (popup "VR mode on this site" button or
  // the __rayneoVRMode() console command); stored in the site's localStorage.
  let userForcedVR = false;
  try { userForcedVR = localStorage.getItem('rayneo-vr-force') === '1'; } catch (e) { /* noop */ }
  const alwaysOfferVR = hostAllowlisted || userForcedVR;

  // An authorized RayNeo device counts as "connected" for advertising and
  // session purposes: after a page reload the driver re-opens the device
  // asynchronously, but sites check isSessionSupported once at load —
  // before reconnection finishes. Without this, sites conclude "no
  // headset" and never re-check.
  async function rayneoReady() {
    if (globalRayNeo.connected) return true;
    try {
      const devices = await navigator.hid.getDevices();
      return devices.some(d =>
        RayNeoHID.VENDOR_IDS.includes(d.vendorId) && RayNeoHID.PRODUCT_IDS.includes(d.productId)
      );
    } catch (e) {
      return false;
    }
  }

  const proxyXR = {
    async isSessionSupported(mode) {
      const result = await this._isSessionSupportedInner(mode);
      // Temporary visibility into what sites ask us (helps debug DeoVR/YouTube)
      console.log('[RayNeo polyfill] isSessionSupported("' + mode + '") ->', result);
      return result;
    },

    async _isSessionSupportedInner(mode) {
      // Disabled via popup toggle -> pretend XR isn't available
      if (window.__rayneoDisabled) {
        return mode === 'inline' && originalXR ? originalXR.isSessionSupported(mode) : false;
      }
      // Connected (or authorized, reconnecting) RayNeo device
      const rayneoSupportsMode = await globalXRSystem.isSessionSupported(mode);
      const rayneoReadyNow = await rayneoReady();
      if (rayneoSupportsMode && rayneoReadyNow) {
        return true;
      }

      // For immersive-vr we can start a session (the connect happens on
      // request) — but only where it is safe to advertise: on known VR
      // player sites, or once the user has actually connected the glasses.
      // This must be checked BEFORE falling back to the real navigator.xr,
      // otherwise desktop Chrome's "false" wins and sites like DeoVR decide
      // there is no headset at all.
      if (mode === 'immersive-vr' && RayNeoHID.isSupported() && (alwaysOfferVR || globalRayNeo.connected)) {
        return true;
      }

      // Fall back to original WebXR if available
      if (originalXR) {
        return originalXR.isSessionSupported(mode);
      }

      return mode === 'inline';
    },

    async requestSession(mode, options) {
      console.log('[RayNeo polyfill] requestSession("' + mode + '")', options || '');
      debugLog('RayNeo WebXR proxy: requestSession', mode, options);

      // Prefer RayNeo for immersive-vr — but only where advertising VR was
      // allowed (known VR sites) or the user explicitly connected the
      // glasses on this page. Otherwise reject like a desktop without a
      // headset would, instead of letting sites auto-enter VR.
      if (mode === 'immersive-vr') {
        if (!alwaysOfferVR && !(await rayneoReady())) {
          debugLog('RayNeo WebXR proxy: refusing immersive-vr (no glasses connected on this site)');
          const err = new Error('No RayNeo glasses connected on this site — connect via the extension popup first.');
          return Promise.reject(err);
        }
        // Connect first (if needed) so the display mode switch starts as
        // early as possible
        if (!globalRayNeo.connected) {
          try {
            await globalRayNeo.checkExistingConnection();
          } catch (e) { /* fall through */ }
          if (!globalRayNeo.connected) {
            try {
              await globalRayNeo.connect();
            } catch (e) {
              debugLog('RayNeo WebXR proxy: Connection failed:', e);
              return Promise.reject(new DOMException('Failed to connect to RayNeo glasses: ' + e.message, 'NotSupportedError'));
            }
          }
        }
        // Switch the panel to SBS NOW and wait for the OS to re-arrange the
        // display: a session created during the switch renders for the stale
        // 1920-wide resolution. Skipped when "auto mode switch" is off in the
        // popup (the user controls the panel mode).
        if (window.__rayneoAutoModeSwitch !== false && globalRayNeo.connected) {
          const baselineWidth = screen.width;
          displaySettling = true;
          displaySettledOnce = false;
          settlingBaselineWidth = baselineWidth;
          await globalRayNeo.setStereo(true);
          await settleDisplayAfterModeChange(baselineWidth);
          displaySettling = false;
          displaySettledOnce = true;
        }
        debugLog('RayNeo WebXR proxy: Using RayNeo for immersive-vr');
        return globalXRSystem.requestSession(mode, options);
      }

      // For inline, use original if available
      if (originalXR && mode === 'inline') {
        try {
          debugLog('RayNeo WebXR proxy: Trying original XR for inline');
          return await originalXR.requestSession(mode, options);
        } catch (e) {
          debugLog('RayNeo WebXR proxy: Original XR failed, falling back to RayNeo');
          return globalXRSystem.requestSession(mode, options);
        }
      }

      return globalXRSystem.requestSession(mode, options);
    },

    addEventListener(type, listener) {
      if (originalXR) {
        originalXR.addEventListener(type, listener);
      }
    },

    removeEventListener(type, listener) {
      if (originalXR) {
        originalXR.removeEventListener(type, listener);
      }
    },

    // Expose RayNeo-specific methods
    get rayneo() {
      return globalRayNeo;
    }
  };

  // Replace navigator.xr
  Object.defineProperty(navigator, 'xr', {
    get: () => proxyXR,
    configurable: true
  });

  // Override XRWebGLLayer to handle RayNeo sessions
  const OriginalXRWebGLLayer = window.XRWebGLLayer;

  window.XRWebGLLayer = function(session, context, options) {
    // Check if this is a RayNeo session
    if (session instanceof RayNeoXRSession) {
      debugLog('Creating RayNeoXRWebGLLayer for RayNeo session');
      return new RayNeoXRWebGLLayer(session, context, options);
    }

    // Fall back to original for real XR sessions
    if (OriginalXRWebGLLayer) {
      return new OriginalXRWebGLLayer(session, context, options);
    }

    // No original XRWebGLLayer, create our polyfill
    return new RayNeoXRWebGLLayer(session, context, options);
  };

  // Copy static properties
  if (OriginalXRWebGLLayer) {
    window.XRWebGLLayer.getNativeFramebufferScaleFactor = function(session) {
      // Our polyfilled sessions have no native framebuffer scale
      if (session instanceof RayNeoXRSession) return 1.0;
      return OriginalXRWebGLLayer.getNativeFramebufferScaleFactor(session);
    };
  } else {
    window.XRWebGLLayer.getNativeFramebufferScaleFactor = function(session) {
      return 1.0;
    };
  }

  // Override XRWebGLBinding: the native constructor (present in Chromium) type-
  // checks its first argument and throws on our polyfilled sessions
  // ("parameter 1 is not of type 'XRSession'"), crashing apps like three.js.
  // Provide a stub for RayNeo sessions. Its prototype deliberately does NOT
  // have createProjectionLayer, so apps that check for it (three.js:
  // 'createProjectionLayer' in XRWebGLBinding.prototype) detect "no layers
  // support" and fall back to the classic XRWebGLLayer path, which this
  // polyfill fully implements.
  const NativeXRWebGLBinding = window.XRWebGLBinding;
  window.XRWebGLBinding = class RayNeoXRWebGLBindingStub {
    constructor(session, context, options) {
      if (session instanceof RayNeoXRSession) {
        debugLog('RayNeoXRWebGLBinding stub created for RayNeo session');
        this.session = session;
        this.context = context;
        return;
      }
      if (NativeXRWebGLBinding) {
        return new NativeXRWebGLBinding(session, context, options);
      }
      throw new TypeError('XRWebGLBinding requires a real XR session');
    }
    // NOTE: no createProjectionLayer on purpose — see comment above.
  };

  // Defer fullscreen requests made while the glasses' display transition is
  // pending: players (DeoVR etc.) call requestFullscreen() themselves the
  // moment they enter VR - before requestSession resolves - and would
  // fullscreen at the stale 1920x1080 arrangement. Hold those calls until
  // the display reports the wide mode, then run them with fresh geometry.
  const nativeRequestFullscreen = Element.prototype.requestFullscreen;
  if (nativeRequestFullscreen) {
    Element.prototype.requestFullscreen = function (...args) {
      if (!displaySettling || displaySettledOnce) {
        return nativeRequestFullscreen.apply(this, args);
      }
      debugLog('RayNeo polyfill: deferring requestFullscreen() until display transition completes');
      return settleDisplayAfterModeChange(settlingBaselineWidth)
        .then(() => nativeRequestFullscreen.apply(this, args));
    };
  }

  // Patch makeXRCompatible: on a desktop browser with no real XR device,
  // the browser's native makeXRCompatible() can stay pending forever, which
  // silently kills apps that do gl.makeXRCompatible().then(setup) — DeoVR's
  // enter-VR chain swallows errors (.catch(() => G=0)), so the hang is
  // invisible. Wrap it: call the original, but race a short timeout that
  // force-resolves true so the app's XR setup always proceeds.
  const patchMakeXRCompatible = (proto) => {
    if (!proto || typeof proto.makeXRCompatible !== 'function') return;
    const original = proto.makeXRCompatible;
    proto.makeXRCompatible = function (...args) {
      console.log('[RayNeo polyfill] makeXRCompatible called');
      let settled = false;
      const origPromise = original.apply(this, args).then((v) => {
        settled = true;
        console.log('[RayNeo polyfill] makeXRCompatible resolved natively:', v);
        return v;
      });
      return Promise.race([
        origPromise.catch((e) => {
          settled = true;
          console.log('[RayNeo polyfill] makeXRCompatible rejected natively, forcing true:', e && e.message);
          return true;
        }),
        new Promise((resolve) => setTimeout(() => {
          if (!settled) {
            console.log('[RayNeo polyfill] makeXRCompatible still pending after 2s - force-resolving true');
          }
          resolve(true);
        }, 2000))
      ]);
    };
  };
  if (window.WebGL2RenderingContext) patchMakeXRCompatible(WebGL2RenderingContext.prototype);
  if (window.WebGLRenderingContext) patchMakeXRCompatible(WebGLRenderingContext.prototype);

  debugLog('RayNeo WebXR polyfill initialized');
  return globalXRSystem;
}

// Expose for manual control
window.RayNeoWebXR = {
  init: initRayNeoWebXR,
  getRayNeo: () => globalRayNeo,
  getRayneo: () => globalRayNeo, // lowercase alias, avoids casing mistakes in the console
  getXRSystem: () => globalXRSystem
};

// Quick diagnostics shortcut for support/debugging
window.__rayneoDiag = function () {
  const d = globalRayNeo ? globalRayNeo.getDiagnostics() : { connected: false, error: 'not initialized' };
  const q = d.quaternion || {};
  const qs = q.w !== undefined
    ? `w:${q.w.toFixed(2)} x:${q.x.toFixed(2)} y:${q.y.toFixed(2)} z:${q.z.toFixed(2)}`
    : 'n/a';
  console.log(`RayNeo diag: connected=${d.connected} reports=${d.reportsReceived} imuFrames=${d.imuFramesParsed} calibrated=${d.biasCalibrated} quaternion=${qs}`);
  // XR session status: how many sessions, and is the app's render loop
  // actually pumping frames (frameCount should rise while you watch it)
  const sess = globalXRSystem && globalXRSystem._sessions ? globalXRSystem._sessions.filter(s => !s.ended) : [];
  sess.forEach((s, i) => {
    const before = s._frameCount || 0;
    setTimeout(() => {
      const after = s._frameCount || 0;
      console.log(`RayNeo xr session[${i}] mode=${s.mode} frames=${before}->${after} (+${(after - before) / 2}/s) stereo=${s.renderState.baseLayer ? 'baseLayer-set' : 'none'}`);
    }, 2000);
  });
  console.log(`RayNeo xr sessions active: ${sess.length}`);
  console.log('  -> frame counter measured over 2 s; ~60/s means the site render loop is running');
  return d;
};

/**
 * RayNeo WebXR Extension - Injected Script
 * This runs in the page context and initializes the WebXR polyfill
 */

// Headset-gate spoofing: some players decide "is there a headset" purely by
// parsing navigator.userAgent for OculusBrowser/PicoBrowser tokens (DeoVR's
// webxr loader is the known case: get_HMD returns NONE=0 for desktop UAs,
// regardless of what navigator.xr reports), so their immersive path never
// activates. Spoof a Quest-3-like UA automatically on DeoVR, and on any site
// where the user enabled "VR mode" for this site (popup button or
// __rayneoVRMode(); stored per-site in localStorage).
(function () {
  let forced = false;
  try { forced = localStorage.getItem('rayneo-vr-force') === '1'; } catch (e) { /* noop */ }
  const deovrHost = /(^|\.)deovr\.com$/.test(location.hostname);
  if (!deovrHost && !forced) return;
  const ua = navigator.userAgent;
  if (ua.includes('OculusBrowser') || ua.includes('PicoBrowser')) return;
  // Add "Quest 3" as the third platform token and append the OculusBrowser
  // token: DeoVR's get_HMD() maps platform token 3 + OculusBrowser -> QUEST_3
  const spoofed = ua.replace(/\(([^)]*)\)/, (m, inner) => `(${inner}; Quest 3)`)
    + ' OculusBrowser/20.1.0.0.137';
  try {
    Object.defineProperty(navigator, 'userAgent', { get: () => spoofed, configurable: true });
    Object.defineProperty(navigator, 'appVersion', { get: () => spoofed.replace('Mozilla/', ''), configurable: true });
    console.log('RayNeo: spoofed UA for headset detection (Quest 3)');
  } catch (e) {
    console.warn('RayNeo: could not override userAgent:', e);
  }
})();


// Initialize immediately
const xrSystem = initRayNeoWebXR();

// Listen for state changes from extension
window.addEventListener('message', async (event) => {
  if (event.source !== window) return;

  const data = event.data;

  if (data.type === 'RAYNEO_STATE_RESPONSE') {
    console.log('RayNeo extension state:', data.state);
  }

  if (data.type === 'RAYNEO_STATE_CHANGED') {
    // Respect the popup's enable toggle even though we load statically
    window.__rayneoDisabled = !(data.state && data.state.enabled);
    // Popup toggle: whether the extension may switch the glasses' display
    // mode (SBS <-> 2D) automatically around VR sessions
    window.__rayneoAutoModeSwitch = !data.state || data.state.autoModeSwitch !== false;
    if (window.__rayneoDisabled) {
      console.log('RayNeo WebXR disabled');
    }
  }

  if (data.type === 'RAYNEO_CONNECT_REQUEST') {
    console.log('RayNeo connect request received');
    try {
      await window.connectRayNeo();
    } catch (e) {
      console.error('Failed to connect RayNeo:', e);
    }
  }

  if (data.type === 'RAYNEO_RECENTER_REQUEST') {
    console.log('RayNeo recenter request received');
    window.recenterRayNeo();
  }

  if (data.type === 'RAYNEO_ENTERVR_REQUEST') {
    // DeoVR (and similar canvas-UI players) expose their internal event bus;
    // event 177 is their "Enter VR" action which requests the XR session
    if (window.MU && typeof MU.events?.emit === 'function') {
      console.log('RayNeo: dispatching Enter VR event to player');
      MU.events.emit(177);
    } else {
      console.warn('RayNeo: no player event bus (window.MU) found on this page');
    }
  }

  if (data.type === 'RAYNEO_YTTRACK_REQUEST') {
    // Toggle head tracking for YouTube's own spherical renderer
    if (typeof window.__rayneoYouTubeTracking === 'function') {
      window.__rayneoYouTubeTracking();
    } else {
      console.warn('RayNeo: YouTube tracking not available on this page');
    }
  }

  if (data.type === 'RAYNEO_VRFORCE_REQUEST') {
    // Toggle per-site "VR mode" (make the site always see a headset), then
    // reload so the site's player re-runs its detection from scratch
    if (typeof window.__rayneoVRMode === 'function') {
      window.__rayneoVRMode();
    }
  }

  if (data.type === 'RAYNEO_RESTORE_2D_REQUEST') {
    // Switch the glasses back to 2D - used when the tab that presented VR
    // content was closed (its session never ended). Any page holding the
    // persistent WebHID grant for the device can do this.
    if (typeof window.__rayneoRestore2D === 'function') {
      window.__rayneoRestore2D().then((success) => {
        window.postMessage({ type: 'RAYNEO_RESTORE_2D_RESULT', success }, '*');
      }).catch(() => {
        window.postMessage({ type: 'RAYNEO_RESTORE_2D_RESULT', success: false }, '*');
      });
    }
  }
});

// Request initial state
window.postMessage({ type: 'RAYNEO_GET_STATE' }, '*');

// Expose manual connect function for debugging
window.connectRayNeo = async function() {
  const rayneo = window.RayNeoWebXR.getRayNeo();
  if (!rayneo) {
    console.error('RayNeo not initialized');
    return;
  }

  try {
    const info = await rayneo.connect();
    console.log('Connected to RayNeo:', info);
    return info;
  } catch (e) {
    console.error('Failed to connect:', e);
    throw e;
  }
};

// Expose recenter function
window.recenterRayNeo = function() {
  const rayneo = window.RayNeoWebXR.getRayNeo();
  if (rayneo && rayneo.connected) {
    rayneo.recenter();
    console.log('RayNeo recentered');
  } else {
    console.error('RayNeo not connected');
  }
};

// Toggle per-site "VR mode": makes this site always see a headset
// (isSessionSupported('immersive-vr') -> true and a Quest-like UA), even
// before the glasses are connected. Takes effect after an automatic reload.
window.__rayneoVRMode = function () {
  let on = false;
  try { on = localStorage.getItem('rayneo-vr-force') === '1'; } catch (e) { /* noop */ }
  try { localStorage.setItem('rayneo-vr-force', on ? '0' : '1'); } catch (e) {
    console.error('RayNeo: cannot write localStorage on this page:', e);
    return;
  }
  console.log('RayNeo: VR mode for this site ' + (on ? 'disabled' : 'enabled') + ' - reloading...');
  setTimeout(() => location.reload(), 400);
};

// Log availability
console.log('RayNeo WebXR ready. WebHID supported:', RayNeoHID.isSupported());

// Dispatch event for pages that want to know when RayNeo is ready
window.dispatchEvent(new CustomEvent('rayneo-webxr-ready', {
  detail: {
    supported: RayNeoHID.isSupported(),
    connect: window.connectRayNeo,
    recenter: window.recenterRayNeo
  }
}));

/**
 * RayNeo YouTube VR mode
 *
 * YouTube's desktop goggles/stereo button is unreliable (their player
 * experiments enable/disable it at random), so this module provides our own:
 * for 360/VR videos it injects a "RayNeo VR" button into the player bar that
 * opens a stereo WebGL overlay rendering the video with head tracking driven
 * directly by the RayNeo IMU - no WebXR involved.
 *
 * Supported layouts (detected from the player response):
 *   - EQUIRECTANGULAR mono  -> full 360 sphere, same image both eyes
 *   - EQUIRECTANGULAR + stereo (qualityLabel like "2160s") -> 360 side-by-side
 *   - MESH (VR180)          -> 180-degree sphere segment, side-by-side
 *
 * Console helpers:
 *   __rayneoYouTubeVR()          enter/exit the VR view
 *   __rayneoYouTubeVRInfo()      show what was detected for this video
 *   __rayneoYouTubeVRMirror()    flip left/right image mapping (if view looks mirrored)
 *   window.recenterRayNeo()      recenter yaw (also key "r" while in VR view)
 */

(function () {
  if (typeof window === 'undefined') return;
  if (!/(^|\.)youtube\.com$/.test(location.hostname)) return;

  const OVERLAY_Z = 2147483647;
  const DEFAULT_FOV = 60; // per-eye vertical FOV, degrees

  const state = {
    active: false,
    canvas: null,
    gl: null,
    program: null,
    buffers: null,
    texture: null,
    video: null,
    raf: 0,
    mode: null, // '360mono' | '360sbs' | '180sbs'
    sbs: false,
    mirror: false,
    ui: null,
    keyHandler: null,
    fsHandler: null
  };

  // ---------------------------------------------------------------- detect

  function getVRInfo() {
    try {
      const player = document.getElementById('movie_player');
      const pr = player && player.getPlayerResponse ? player.getPlayerResponse() : null;
      if (!pr || !pr.streamingData) return null;

      const fmts = [
        ...(pr.streamingData.formats || []),
        ...(pr.streamingData.adaptiveFormats || [])
      ];

      let projection = null;
      let stereo = false;

      for (const f of fmts) {
        if (f.projectionType && f.projectionType !== 'RECTANGULAR') {
          projection = f.projectionType;
          // MESH is YouTube's VR180 format, which is always stereo
          if (f.projectionType === 'MESH') stereo = true;
        }
        // "2160s"-style quality labels mark stereoscopic streams
        if (f.qualityLabel && /^\d+s$/.test(f.qualityLabel)) stereo = true;
      }

      if (!projection) return null;

      const mode = projection === 'MESH'
        ? '180sbs'
        : (stereo ? '360sbs' : '360mono');

      return { projection, stereo, mode };
    } catch (e) {
      console.warn('[RayNeo YouTube VR] detection failed:', e);
      return null;
    }
  }

  // ------------------------------------------------------------ button

  function makeGogglesIcon() {
    // YouTube enforces Trusted Types, so innerHTML with SVG markup throws.
    // Build the SVG through the DOM API instead. Stroke-based eyeglasses
    // (two lenses + bridge + temple arms) so it reads clearly at 22px.
    const NS = 'http://www.w3.org/2000/svg';
    const svg = document.createElementNS(NS, 'svg');
    svg.setAttribute('viewBox', '0 0 24 24');
    svg.style.width = '22px';
    svg.style.height = '22px';
    svg.style.display = 'block';

    const g = document.createElementNS(NS, 'g');
    g.setAttribute('fill', 'none');
    g.style.stroke = '#fff';
    g.style.strokeWidth = '2';
    g.style.strokeLinecap = 'round';
    g.style.strokeLinejoin = 'round';

    const lens = (cx) => {
      const c = document.createElementNS(NS, 'circle');
      c.setAttribute('cx', cx);
      c.setAttribute('cy', '15');
      c.setAttribute('r', '4');
      return c;
    };
    const arm = (d) => {
      const p = document.createElementNS(NS, 'path');
      p.setAttribute('d', d);
      return p;
    };

    g.appendChild(lens(6));
    g.appendChild(lens(18));
    g.appendChild(arm('M14 15a2 2 0 0 0-2-2 2 2 0 0 0-2 2'));          // bridge
    g.appendChild(arm('M2.5 13 5 7c.7-1.3 1.4-2 3-2'));                 // left arm
    g.appendChild(arm('M21.5 13 19 7c-.7-1.3-1.5-2-3-2'));              // right arm
    svg.appendChild(g);
    return svg;
  }

  function ensureButton() {
    if (!/^\/watch/.test(location.pathname)) return;
    ensureStyles();

    const info = getVRInfo();
    const existing = document.getElementById('rayneo-vr-btn');
    if (!info) {
      if (existing) existing.remove();
      return;
    }

    const controls = document.querySelector('.ytp-right-controls');
    if (!controls || existing) return;

    const btn = document.createElement('button');
    btn.id = 'rayneo-vr-btn';
    btn.className = 'ytp-button';
    btn.title = 'RayNeo head tracking (YouTube view)';
    btn.appendChild(makeGogglesIcon());
    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      toggleTracking();
    });
    controls.insertBefore(btn, controls.firstChild);
  }

  // ------------------------------------------------------------ WebGL core

  const VERT_SRC =
    'attribute vec3 aPos;\n' +
    'attribute vec2 aUV;\n' +
    'uniform mat4 uVP;\n' +
    'varying vec2 vUV;\n' +
    'void main(){ gl_Position = uVP * vec4(aPos, 1.0); vUV = aUV; }';

  const FRAG_SRC =
    'precision mediump float;\n' +
    'varying vec2 vUV;\n' +
    'uniform sampler2D uTex;\n' +
    'uniform float uSbs;\n' +
    'uniform float uEye;\n' +
    'uniform float uMirror;\n' +
    'void main(){\n' +
    '  float u = vUV.x;\n' +
    '  if (uSbs > 0.5) u = uEye * 0.5 + u * 0.5;\n' +
    '  u = mix(u, 1.0 - u, uMirror);\n' +
    '  gl_FragColor = texture2D(uTex, vec2(u, vUV.y));\n' +
    '}';

  function mat4Mul(a, b) {
    // column-major a*b
    const o = new Float32Array(16);
    for (let c = 0; c < 4; c++) {
      for (let r = 0; r < 4; r++) {
        o[c * 4 + r] =
          a[r] * b[c * 4] +
          a[4 + r] * b[c * 4 + 1] +
          a[8 + r] * b[c * 4 + 2] +
          a[12 + r] * b[c * 4 + 3];
      }
    }
    return o;
  }

  function perspective(fovyRad, aspect, near, far) {
    const f = 1 / Math.tan(fovyRad / 2);
    const nf = 1 / (near - far);
    const m = new Float32Array(16);
    m[0] = f / aspect; m[5] = f;
    m[10] = (far + near) * nf; m[11] = -1;
    m[14] = 2 * far * near * nf;
    return m;
  }

  // Same convention as the WebXR polyfill's RayNeoXRRigidTransform: the driver
  // quaternion maps viewer -> world (x right, y up, -z forward). Camera sits
  // at the origin, so the view matrix is just the transpose (inverse) of the
  // world rotation.
  function viewFromQuaternion(q) {
    const x2 = q.x + q.x, y2 = q.y + q.y, z2 = q.z + q.z;
    const xx = q.x * x2, xy = q.x * y2, xz = q.x * z2;
    const yy = q.y * y2, yz = q.y * z2, zz = q.z * z2;
    const wx = q.w * x2, wy = q.w * y2, wz = q.w * z2;

    // rotation matrix (column-major)
    const r = new Float32Array(16);
    r[0] = 1 - (yy + zz); r[1] = xy + wz; r[2] = xz - wy;
    r[4] = xy - wz; r[5] = 1 - (xx + zz); r[6] = yz + wx;
    r[8] = xz + wy; r[9] = yz - wx; r[10] = 1 - (xx + yy);
    r[15] = 1;

    // transpose -> view matrix
    const v = new Float32Array(16);
    v[0] = r[0]; v[1] = r[4]; v[2] = r[8];  v[3] = 0;
    v[4] = r[1]; v[5] = r[5]; v[6] = r[9];  v[7] = 0;
    v[8] = r[2]; v[9] = r[6]; v[10] = r[10]; v[11] = 0;
    v[12] = 0; v[13] = 0; v[14] = 0; v[15] = 1;
    return v;
  }

  function identityQuaternion() {
    return { x: 0, y: 0, z: 0, w: 1 };
  }

  function getOrientation() {
    try {
      const rayneo = window.RayNeoWebXR && window.RayNeoWebXR.getRayneo();
      if (rayneo && rayneo.connected) return rayneo.getQuaternion();
    } catch (e) { /* fall through */ }
    return identityQuaternion();
  }

  function buildGeometry(gl, mode) {
    // Sphere segment covering the video's yaw span, UVs normalized 0..1
    // across that span (fragment shader adds the eye's half for SBS).
    const yawSpan = mode === '180sbs' ? Math.PI : Math.PI * 2;
    const yawStart = mode === '180sbs' ? -Math.PI / 2 : -Math.PI;

    const SEG_U = 64, SEG_V = 48;
    const verts = new Float32Array((SEG_U + 1) * (SEG_V + 1) * 5);
    let vi = 0;
    for (let j = 0; j <= SEG_V; j++) {
      // v: 0 = image bottom (down), 1 = image top (up)
      const pitch = -Math.PI / 2 + (j / SEG_V) * Math.PI;
      for (let i = 0; i <= SEG_U; i++) {
        const u = i / SEG_U;
        const yaw = yawStart + u * yawSpan;
        const cp = Math.cos(pitch);
        verts[vi++] = Math.sin(yaw) * cp;          // x
        verts[vi++] = Math.sin(pitch);             // y
        verts[vi++] = -Math.cos(yaw) * cp;         // z (forward at yaw=0)
        verts[vi++] = u;
        verts[vi++] = j / SEG_V;
      }
    }

    const idx = new Uint16Array(SEG_U * SEG_V * 6);
    let ii = 0;
    for (let j = 0; j < SEG_V; j++) {
      for (let i = 0; i < SEG_U; i++) {
        const a = j * (SEG_U + 1) + i;
        const b = a + 1;
        const c = a + SEG_U + 1;
        const d = c + 1;
        idx[ii++] = a; idx[ii++] = c; idx[ii++] = b;
        idx[ii++] = b; idx[ii++] = c; idx[ii++] = d;
      }
    }

    const posBuf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, posBuf);
    gl.bufferData(gl.ARRAY_BUFFER, verts, gl.STATIC_DRAW);
    const idxBuf = gl.createBuffer();
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, idxBuf);
    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, idx, gl.STATIC_DRAW);

    return { posBuf, idxBuf, count: idx.length };
  }

  function compileShader(gl, type, src) {
    const sh = gl.createShader(type);
    gl.shaderSource(sh, src);
    gl.compileShader(sh);
    if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) {
      throw new Error('shader: ' + gl.getShaderInfoLog(sh));
    }
    return sh;
  }

  function createProgram(gl) {
    const prog = gl.createProgram();
    gl.attachShader(prog, compileShader(gl, gl.VERTEX_SHADER, VERT_SRC));
    gl.attachShader(prog, compileShader(gl, gl.FRAGMENT_SHADER, FRAG_SRC));
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
      throw new Error('link: ' + gl.getProgramInfoLog(prog));
    }
    return prog;
  }

  function makeTexture(gl) {
    const tex = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, tex);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true);
    // 1x1 placeholder until the first video frame is available
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE,
      new Uint8Array([0, 0, 0, 255]));
    return tex;
  }

  let styleAdded = false;
  function ensureStyles() {
    if (styleAdded) return;
    styleAdded = true;
    const st = document.createElement('style');
    st.textContent =
      '#rayneo-vr-btn{display:flex;align-items:center;justify-content:center;width:48px;color:#fff;opacity:.9}' +
      '#rayneo-vr-btn:hover{opacity:1}' +
      '#rayneo-vr-btn.rayneo-tracking{color:#f90;opacity:1;}' +
      '#rayneo-vr-btn.rayneo-tracking svg g{stroke:#f90;}';
    (document.head || document.documentElement).appendChild(st);
  }

  // ------------------------------------------------------- tracking mode
  // Drives YouTube's own spherical renderer (movie_player) from the IMU:
  // quaternion -> yaw/pitch (degrees) -> setSphericalProperties each frame.
  // No custom rendering; YouTube handles mesh/projection/stereo itself.

  const tracking = {
    active: false,
    raf: 0,
    qSmooth: null,   // smoothed orientation
    flipYaw: false,
    flipPitch: false,
    keyHandler: null,
    lastWarn: 0
  };

  function rotateVec(q, v) {
    // rotate vector v by quaternion q (standard q*v*q*)
    const qx = q.x, qy = q.y, qz = q.z, qw = q.w;
    const tx = 2 * (qy * v[2] - qz * v[1]);
    const ty = 2 * (qz * v[0] - qx * v[2]);
    const tz = 2 * (qx * v[1] - qy * v[0]);
    return [
      v[0] + qw * tx + (qy * tz - qz * ty),
      v[1] + qw * ty + (qz * tx - qx * tz),
      v[2] + qw * tz + (qx * ty - qy * tx)
    ];
  }

  function nlerp(a, b, t) {
    // shortest-path lerp + normalize
    const dot = a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
    const s = dot < 0 ? -t : t;
    const bs = dot < 0 ? { x: -b.x, y: -b.y, z: -b.z, w: -b.w } : b;
    const r = {
      x: a.x * (1 - t) + bs.x * t,
      y: a.y * (1 - t) + bs.y * t,
      z: a.z * (1 - t) + bs.z * t,
      w: a.w * (1 - t) + bs.w * t
    };
    const len = Math.hypot(r.x, r.y, r.z, r.w) || 1;
    return { x: r.x / len, y: r.y / len, z: r.z / len, w: r.w / len };
  }

  function trackingFrame() {
    if (!tracking.active) return;
    tracking.raf = requestAnimationFrame(trackingFrame);

    // Stop when the user navigates away from a watch page
    if (!/^\/watch/.test(location.pathname)) { stopTracking(); return; }

    const q = getOrientation();
    if (!q) return;

    tracking.qSmooth = tracking.qSmooth ? nlerp(tracking.qSmooth, q, 0.35) : q;
    const qs = tracking.qSmooth;

    // Camera forward vector in world space (viewer looks along -z)
    const f = rotateVec(qs, [0, 0, -1]);
    const len = Math.hypot(f[0], f[1], f[2]) || 1;
    f[0] /= len; f[1] /= len; f[2] /= len;

    let yaw = Math.atan2(f[0], -f[2]) * 180 / Math.PI;
    let pitch = Math.asin(Math.max(-1, Math.min(1, -f[1]))) * 180 / Math.PI;
    // YouTube pans opposite to the natural convention; invert both so the
    // view follows the head direction.
    yaw = -yaw;
    pitch = -pitch;
    if (tracking.flipYaw) yaw = -yaw;
    if (tracking.flipPitch) pitch = -pitch;

    const player = document.getElementById('movie_player');
    if (player && typeof player.setSphericalProperties === 'function') {
      player.setSphericalProperties({ yaw, pitch });
    } else if (Date.now() - tracking.lastWarn > 5000) {
      tracking.lastWarn = Date.now();
      console.warn('[RayNeo YouTube tracking] movie_player API unavailable');
    }
  }

  function setButtonState() {
    const btn = document.getElementById('rayneo-vr-btn');
    if (btn) btn.classList.toggle('rayneo-tracking', tracking.active);
  }

  function startTracking() {
    if (tracking.active) return;
    tracking.active = true;
    tracking.flipYaw = localStorage.getItem('rayneo-yt-flip-yaw') === '1';
    tracking.flipPitch = localStorage.getItem('rayneo-yt-flip-pitch') === '1';
    tracking.qSmooth = null;

    tracking.keyHandler = (e) => {
      if (e.key === 'Escape') { e.stopPropagation(); stopTracking(); return; }
      if (e.key === 'r' || e.key === 'R') {
        e.stopPropagation(); e.preventDefault();
        try { window.recenterRayNeo(); } catch (err) { /* noop */ }
      }
    };
    window.addEventListener('keydown', tracking.keyHandler, true);

    setButtonState();
    console.log('[RayNeo YouTube tracking] started - Esc stops, R recenters');
    tracking.raf = requestAnimationFrame(trackingFrame);
  }

  function stopTracking() {
    if (!tracking.active) return;
    tracking.active = false;
    cancelAnimationFrame(tracking.raf);
    if (tracking.keyHandler) window.removeEventListener('keydown', tracking.keyHandler, true);
    tracking.keyHandler = null;
    setButtonState();
    console.log('[RayNeo YouTube tracking] stopped');
  }

  function toggleTracking() {
    tracking.active ? stopTracking() : startTracking();
  }

  window.__rayneoYouTubeTracking = toggleTracking;
  window.__rayneoYouTubeFlip = function () {
    tracking.flipYaw = !tracking.flipYaw;
    localStorage.setItem('rayneo-yt-flip-yaw', tracking.flipYaw ? '1' : '0');
    console.log('[RayNeo YouTube tracking] flip yaw:', tracking.flipYaw);
  };
  window.__rayneoYouTubeFlipPitch = function () {
    tracking.flipPitch = !tracking.flipPitch;
    localStorage.setItem('rayneo-yt-flip-pitch', tracking.flipPitch ? '1' : '0');
    console.log('[RayNeo YouTube tracking] flip pitch:', tracking.flipPitch);
  };

  // ------------------------------------------------------------- overlay UI

  function buildOverlayUI() {
    const ui = document.createElement('div');
    ui.style.cssText =
      'position:fixed;top:0;right:0;z-index:' + (OVERLAY_Z + 1) +
      ';display:flex;gap:8px;padding:12px;';

    const mkBtn = (label, fn) => {
      const b = document.createElement('button');
      b.textContent = label;
      b.style.cssText =
        'background:rgba(0,0,0,.6);color:#fff;border:1px solid rgba(255,255,255,.4);' +
        'border-radius:4px;padding:8px 14px;font:14px Roboto,Arial,sans-serif;cursor:pointer;';
      b.addEventListener('click', fn);
      ui.appendChild(b);
      return b;
    };

    mkBtn('Recenter', () => {
      try { window.recenterRayNeo(); } catch (e) { /* noop */ }
    });
    mkBtn('Mirror', () => toggleMirror());
    mkBtn('Exit VR', () => exitYouTubeVR());

    const status = document.createElement('div');
    status.id = 'rayneo-vr-status';
    status.style.cssText =
      'position:fixed;top:0;left:0;z-index:' + (OVERLAY_Z + 1) +
      ';color:#fff;background:rgba(0,0,0,.6);border-radius:4px;' +
      'padding:10px 14px;font:13px Roboto,Arial,sans-serif;max-width:60vw;';
    ui.appendChild(status);
    return { ui, status };
  }

  function updateStatus() {
    const el = document.getElementById('rayneo-vr-status');
    if (!el) return;
    const rayneo = (() => {
      try { return window.RayNeoWebXR && window.RayNeoWebXR.getRayneo(); } catch (e) { return null; }
    })();
    const connected = !!(rayneo && rayneo.connected);
    const modeNames = {
      '360mono': '360° mono',
      '360sbs': '360° stereo (SBS)',
      '180sbs': 'VR180 stereo (SBS)'
    };
    el.textContent = connected
      ? ('RayNeo VR · ' + (modeNames[state.mode] || state.mode) + ' · Esc exit · R recenter')
      : 'RayNeo VR · glasses NOT connected (run connect in extension popup) · Esc exit';
  }

  // ------------------------------------------------------------ enter/exit

  function findVideo() {
    return document.querySelector('video.html5-main-video') ||
      document.querySelector('video');
  }

  function enterYouTubeVR() {
    if (state.active) return;

    const video = findVideo();
    if (!video) {
      console.warn('[RayNeo YouTube VR] no <video> element found');
      return;
    }

    const info = getVRInfo();
    state.mode = (info && info.mode) || '360sbs';
    state.sbs = state.mode !== '360mono';
    console.log('[RayNeo YouTube VR] entering, mode:', state.mode,
      info ? '(detected: ' + info.projection + (info.stereo ? ', stereo' : '') + ')' : '(detection unavailable, defaulting to 360 SBS)');

    const canvas = document.createElement('canvas');
    canvas.id = 'rayneo-vr-canvas';
    canvas.style.cssText =
      'position:fixed;inset:0;width:100vw;height:100vh;z-index:' + OVERLAY_Z +
      ';background:#000;display:block;cursor:none;';
    document.documentElement.appendChild(canvas);

    const gl = canvas.getContext('webgl', { antialias: true, alpha: false });
    if (!gl) {
      canvas.remove();
      console.error('[RayNeo YouTube VR] WebGL unavailable');
      return;
    }

    const prog = createProgram(gl);
    const geom = buildGeometry(gl, state.mode);
    const tex = makeTexture(gl);

    const aPos = gl.getAttribLocation(prog, 'aPos');
    const aUV = gl.getAttribLocation(prog, 'aUV');
    const uVP = gl.getUniformLocation(prog, 'uVP');
    const uSbs = gl.getUniformLocation(prog, 'uSbs');
    const uEye = gl.getUniformLocation(prog, 'uEye');
    const uMirror = gl.getUniformLocation(prog, 'uMirror');

    gl.useProgram(prog);
    gl.bindBuffer(gl.ARRAY_BUFFER, geom.posBuf);
    gl.enableVertexAttribArray(aPos);
    gl.vertexAttribPointer(aPos, 3, gl.FLOAT, false, 20, 0);
    gl.enableVertexAttribArray(aUV);
    gl.vertexAttribPointer(aUV, 2, gl.FLOAT, false, 20, 12);
    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, geom.idxBuf);

    const { ui, status } = buildOverlayUI();
    document.documentElement.appendChild(ui);

    Object.assign(state, {
      active: true, canvas, gl, program: prog, buffers: geom, texture: tex,
      video, ui, status, aPos, aUV, uVP, uSbs, uEye, uMirror, raf: 0
    });
    state.mirror = localStorage.getItem('rayneo-ytvr-mirror') === '1';
    updateStatus();

    // Overlay owns the keyboard while active: Esc exits, R recenters.
    state.keyHandler = (e) => {
      if (e.key === 'Escape') { e.stopPropagation(); exitYouTubeVR(); return; }
      if (e.key === 'r' || e.key === 'R') {
        e.stopPropagation(); e.preventDefault();
        try { window.recenterRayNeo(); } catch (err) { /* noop */ }
      }
    };
    window.addEventListener('keydown', state.keyHandler, true);

    state.fsHandler = () => resize();
    window.addEventListener('resize', state.fsHandler);

    document.documentElement.requestFullscreen().catch(() => {});
    state.raf = requestAnimationFrame(frame);
  }

  function exitYouTubeVR() {
    if (!state.active) return;
    state.active = false;
    cancelAnimationFrame(state.raf);

    if (state.keyHandler) window.removeEventListener('keydown', state.keyHandler, true);
    if (state.fsHandler) window.removeEventListener('resize', state.fsHandler);

    if (document.fullscreenElement) {
      document.exitFullscreen().catch(() => {});
    }

    const { canvas, gl, texture, buffers, program, ui } = state;
    if (gl) {
      if (buffers) {
        gl.deleteBuffer(buffers.posBuf);
        gl.deleteBuffer(buffers.idxBuf);
      }
      if (texture) gl.deleteTexture(texture);
      if (program) gl.deleteProgram(program);
    }
    if (canvas) canvas.remove();
    if (ui) ui.remove();

    Object.assign(state, {
      canvas: null, gl: null, program: null, buffers: null, texture: null,
      video: null, ui: null, status: null, keyHandler: null, fsHandler: null
    });
    console.log('[RayNeo YouTube VR] exited');
  }

  function toggleMirror() {
    state.mirror = !state.mirror;
    localStorage.setItem('rayneo-ytvr-mirror', state.mirror ? '1' : '0');
    console.log('[RayNeo YouTube VR] mirror:', state.mirror);
    updateStatus();
  }

  // ---------------------------------------------------------------- render

  function resize() {
    if (!state.canvas) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const w = Math.round(window.innerWidth * dpr);
    const h = Math.round(window.innerHeight * dpr);
    if (state.canvas.width !== w || state.canvas.height !== h) {
      state.canvas.width = w;
      state.canvas.height = h;
    }
  }

  function frame(timestamp) {
    if (!state.active) return;
    state.raf = requestAnimationFrame(frame);

    const gl = state.gl;
    const video = state.video;
    resize();

    if (video && video.readyState >= 2 && video.videoWidth > 0) {
      gl.bindTexture(gl.TEXTURE_2D, state.texture);
      try {
        gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, video);
      } catch (e) { /* cross-origin or empty frame: keep last texture */ }
    }

    const q = getOrientation();
    const view = viewFromQuaternion(q);

    const w = state.canvas.width, h = state.canvas.height;
    const aspect = (w / 2) / h;
    const proj = perspective(DEFAULT_FOV * Math.PI / 180, aspect, 0.05, 50);
    const vp = mat4Mul(proj, view);

    gl.viewport(0, 0, w, h);
    gl.clearColor(0, 0, 0, 1);
    gl.clear(gl.COLOR_BUFFER_BIT);

    gl.useProgram(state.program);
    gl.bindTexture(gl.TEXTURE_2D, state.texture);
    gl.uniform1f(state.uSbs, state.sbs ? 1 : 0);
    gl.uniform1f(state.uMirror, state.mirror ? 1 : 0);

    gl.uniformMatrix4fv(state.uVP, false, vp);
    gl.uniform1f(state.uEye, 0);
    gl.viewport(0, 0, w / 2, h);
    gl.drawElements(gl.TRIANGLES, state.buffers.count, gl.UNSIGNED_SHORT, 0);

    gl.uniform1f(state.uEye, 1);
    gl.viewport(w / 2, 0, w / 2, h);
    gl.drawElements(gl.TRIANGLES, state.buffers.count, gl.UNSIGNED_SHORT, 0);
  }

  // ------------------------------------------------------------- public API

  window.__rayneoYouTubeVR = function () {
    state.active ? exitYouTubeVR() : enterYouTubeVR();
  };

  window.__rayneoYouTubeVRInfo = function () {
    const info = getVRInfo();
    console.log('[RayNeo YouTube VR] detected:', info || 'not a VR video (or player API unavailable)');
    return info;
  };

  window.__rayneoYouTubeVRMirror = function () {
    toggleMirror();
  };

  // Poll for watch pages: YouTube is a SPA, so the button must be re-added
  // as the user navigates between videos.
  setInterval(ensureButton, 1500);

  console.log('[RayNeo YouTube VR] ready - VR videos get a "RayNeo VR" button; '
    + 'or run __rayneoYouTubeVR() in the console');
})();
